import React, { useState } from 'react';
import AgentGrid from './AgentGrid';
import A2APanel from './A2APanel';
import LogsPanel from './LogsPanel';

function MainContent({
  currentUser,
  onLogout,
  agents,
  purchasedMap,
  accessStatus,
  logs,
  commHistory,
  authToken,
  apiBase,
  onLoadAgents,
  onLoadLogs,
  onLoadHistory
}) {
  const [activeTab, setActiveTab] = useState('marketplace');

  return (
    <div className="app-container">
      <header className="header">
        <h1>🤖 Agent Marketplace</h1>
        <div className="user-info">
          <span>Logged in as: <strong>{currentUser}</strong></span>
          <button className="logout-btn" onClick={onLogout}>
            Logout
          </button>
        </div>
      </header>

      <main className="main-content">
        <div className="tabs">
          <button
            className={`tab-btn ${activeTab === 'marketplace' ? 'active' : ''}`}
            onClick={() => setActiveTab('marketplace')}
          >
            💼 Marketplace
          </button>
          <button
            className={`tab-btn ${activeTab === 'a2a' ? 'active' : ''}`}
            onClick={() => setActiveTab('a2a')}
          >
            💬 A2A Communication
          </button>
          <button
            className={`tab-btn ${activeTab === 'logs' ? 'active' : ''}`}
            onClick={() => setActiveTab('logs')}
          >
            📊 Logs
          </button>
        </div>

        <div className={`tab-content ${activeTab === 'marketplace' ? 'active' : ''}`}>
          <AgentGrid
            agents={agents}
            purchasedMap={purchasedMap}
            accessStatus={accessStatus}
            authToken={authToken}
            apiBase={apiBase}
            onLoadAgents={onLoadAgents}
          />
        </div>

        <div className={`tab-content ${activeTab === 'a2a' ? 'active' : ''}`}>
          <A2APanel
            agents={agents}
            commHistory={commHistory}
            authToken={authToken}
            apiBase={apiBase}
            onLoadHistory={onLoadHistory}
          />
        </div>

        <div className={`tab-content ${activeTab === 'logs' ? 'active' : ''}`}>
          <LogsPanel
            logs={logs}
            authToken={authToken}
            apiBase={apiBase}
            onLoadLogs={onLoadLogs}
          />
        </div>
      </main>
    </div>
  );
}

export default MainContent;
